import path from 'node:path';
import { SyncConfig } from '../config.js';
import { createEmptyResult, type GeneratorResult } from '../results.js';
import { safeWriteFile } from '../fs-utils.js';

/**
 * Generates stub barrel files for missing domain/application/infrastructure pieces.
 * Uses safeWriteFile for dry-run safety, protection, and idempotency.
 * Stamps each barrel with @generated marker.
 */
export async function generateStubs(
  moduleDir: string,
  config: SyncConfig
): Promise<GeneratorResult> {
  const result = createEmptyResult();

  const stubs = [
    // Domain barrel
    {
      dir: 'domain',
      file: 'index.ts',
      content: `// @generated by @hexagen/sync\n\nexport {};\n`,
    },
    // Application ports/in barrel
    {
      dir: 'application/ports/in',
      file: 'index.ts',
      content: `// @generated by @hexagen/sync\n\nexport {};\n`,
    },
    // Application ports/out barrel
    {
      dir: 'application/ports/out',
      file: 'index.ts',
      content: `// @generated by @hexagen/sync\n\nexport {};\n`,
    },
    // Application use-cases barrel
    {
      dir: 'application/use-cases',
      file: 'index.ts',
      content: `// @generated by @hexagen/sync\n\nexport {};\n`,
    },
    // Infrastructure adapters barrel
    {
      dir: 'infrastructure/adapters',
      file: 'index.ts',
      content: `// @generated by @hexagen/sync\n\nexport {};\n`,
    },
  ];

  for (const stub of stubs) {
    const filePath = path.join(moduleDir, stub.dir, stub.file);
    const status = await safeWriteFile(filePath, stub.content, config);

    if (status === 'created') result.created.push(filePath);
    if (status === 'updated') result.updated.push(filePath);
    if (status === 'skipped' || status === 'protected')
      result.skipped.push(filePath);
    result.totalOps += status === 'created' || status === 'updated' ? 1 : 0;
  }

  return result;
}
